package dev.kelmagic.client;
import dev.kelmagic.*;import dev.kelmagic.research.*;import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.*;import net.minecraft.util.FormattedCharSequence;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;
/** A separate, paginated book. Knowledge never has a permanent side panel. */
public final class ResearchEntryScreen extends Screen {
 private final CodexScreen parent;private final ResearchCatalog.Node node;private final List<List<FormattedCharSequence>> pages=new ArrayList<>(),uses=new ArrayList<>();
 private final List<Map.Entry<int[],ItemStack>> recipeHover=new ArrayList<>();private float uiScale=1;private int x,y,spread;private boolean learned;
 public ResearchEntryScreen(CodexScreen parent,ResearchCatalog.Node node){super(Component.literal(CodexScreen.nodeName(node)));this.parent=parent;this.node=node;}
 @Override protected void init(){uiScale=Math.min(1,Math.min((width-8)/360f,(height-8)/216f));x=((int)(width/uiScale)-360)/2;y=((int)(height/uiScale)-216)/2;learned=parent.entryLearned(node);pages.clear();uses.clear();MutableComponent prose;if(learned){prose=Component.empty().append(Component.literal(node.thought()).withStyle(v->v.withColor(0x315B61).withItalic(true))).append("\n\n").append(Component.translatable(node.lore()).withStyle(net.minecraft.ChatFormatting.DARK_GRAY));}else{int done=Research.progress(ResearchClient.state,node);String hint=node.sealed()?"Эти строки ещё не открылись. Способ их чтения пока неизвестен.":done>=node.steps().size()?"Наблюдения завершены. Лист превратился в открытие: возьмите его в руку и прочитайте, чтобы сохранить понимание.":node.steps().get(done).hint();prose=Component.literal((parent.creativeResearch()?"Наблюдения: "+done+"/"+node.steps().size():"Наблюдения")+"\n\n"+hint).withStyle(net.minecraft.ChatFormatting.DARK_GRAY);if(done>0)prose.append(Component.literal("\n\n"+node.steps().get(done-1).comment()).withStyle(v->v.withColor(0x315B61).withItalic(true)));}
 if(parent.creativeResearch())prose.append("\n\n").append(Component.literal(ResearchOpeningGuide.describe(node)).withStyle(net.minecraft.ChatFormatting.DARK_GRAY));
 var lines=font.split(prose,132);for(int i=0;i<lines.size();i+=12)pages.add(List.copyOf(lines.subList(i,Math.min(i+12,lines.size()))));if(pages.isEmpty())pages.add(List.of());if(pages.size()%2!=0)pages.add(List.of());String usageText=node.example();if(CodexScreen.documentedRite(node)){var rite=dev.kelmagic.core.GrandSpells.ALL.stream().filter(r->("rite:"+r.id()).equals(node.id())).findFirst().orElseThrow();usageText="Полная формула ("+rite.formula().size()+" слов):\n\n"+String.join(" ",rite.formula());}var usage=font.split(Component.literal(usageText),132);for(int i=0;i<usage.size();i+=13)uses.add(List.copyOf(usage.subList(i,Math.min(i+13,usage.size()))));if(uses.isEmpty())uses.add(List.of());spread=Math.clamp(spread,0,totalSpreads()-1);addRenderableWidget(CodexPaint.button(font,"‹",x+20,y+188,28,16,()->turn(-1)));addRenderableWidget(CodexPaint.button(font,"›",x+312,y+188,28,16,()->turn(1)));addRenderableWidget(CodexPaint.backArrow(font,x+167,y+176,this::onClose));}
 private void turn(int direction){Runnable apply=()->spread=Math.clamp(spread+direction,0,totalSpreads()-1);if(parent.tableView()!=null)parent.tableView().turn(false,direction,apply);else apply.run();}
 private int recipeCount(){if(CodexScreen.documentedRite(node))return 0;if(node.id().equals("midnight_wood"))return 3;if(node.id().equals("archivist_table")||node.id().equals("archivist_cabinet"))return 2;return node.id().equals("arcane_armor")||node.id().equals("mage_robes")||node.id().equals("archivist_robes")?4:1;}
 private int totalSpreads(){return pages.size()/2+(learned?recipeCount()+(CodexScreen.documentedRite(node)?(uses.size()+1)/2:uses.size()/2):0);}
 public void researchChanged(){rebuildWidgets();}
 @Override public void render(GuiGraphics g,int mx,int my,float partial){if(parent.tableView()==null)renderBackground(g,mx,my,partial);g.pose().pushPose();g.pose().scale(uiScale,uiScale,1);mx=(int)(mx/uiScale);my=(int)(my/uiScale);g.blit(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath(KelMagic.MODID,"textures/gui/codex_entry.png"),x,y,0,0,360,216,360,216);g.pose().pushPose();g.pose().translate(0,-8,0);CodexPaint.dust(g,x,y,System.currentTimeMillis());g.drawString(font,font.plainSubstrByWidth(CodexScreen.nodeName(node),306),x+25,y+27,0xFFE3C58F,false);recipeHover.clear();if(spread<pages.size()/2){drawPage(g,pages.get(spread*2),x+25);drawPage(g,pages.get(spread*2+1),x+196);}else if(CodexScreen.documentedRite(node)){int first=(spread-pages.size()/2)*2;drawUse(g,first,x+25,y+47);drawUse(g,first+1,x+196,y+47);}else if(spread<pages.size()/2+recipeCount()){recipe(g);drawUse(g,0,x+196,y+47);}else{int first=(spread-pages.size()/2-recipeCount())*2+1;drawUse(g,first,x+25,y+47);drawUse(g,first+1,x+196,y+47);}
 g.pose().popPose();if(parent.creativeResearch())g.drawCenteredString(font,(spread+1)+" / "+totalSpreads(),x+270,y+192,0xFFE0C59A);for(var w:renderables)w.render(g,mx,my,partial);for(var h:recipeHover){var r=h.getKey();if(mx>=r[0]&&mx<r[0]+18&&my>=r[1]&&my<r[1]+18)tooltip(g,h.getValue(),mx,my);}g.pose().popPose();}
 private void tooltip(GuiGraphics g,ItemStack item,int mx,int my){var tip=parent.creativeResearch()?Screen.getTooltipFromItem(Minecraft.getInstance(),item):List.of(item.getHoverName());if(parent.tableView()!=null){TableBookView.tooltip(g,font,tip,mx,my);return;}g.pose().popPose();g.renderComponentTooltip(font,tip,(int)(mx*uiScale),(int)(my*uiScale));g.pose().pushPose();g.pose().scale(uiScale,uiScale,1);}
 private void drawUse(GuiGraphics g,int index,int left,int top){if(index>=uses.size())return;var lines=uses.get(index);for(int i=0;i<lines.size();i++)g.drawString(font,lines.get(i),left,top+i*10,CodexPaint.INK,false);}
 private void drawPage(GuiGraphics g,List<FormattedCharSequence> lines,int left){for(int i=0;i<lines.size();i++)g.drawString(font,lines.get(i),left,y+47+i*10,CodexPaint.INK,false);}
 private void item(GuiGraphics g,ItemStack s,int left,int top){g.renderItem(s,left,top);if(parent.creativeResearch())g.renderItemDecorations(font,s,left,top);recipeHover.add(Map.entry(new int[]{left,top-8},s));}
 private void recipe(GuiGraphics g){int left=x+25,top=y+66;CodexPaint.text(g,font,"Восстановленная схема",left,y+47,132,2);if(node.id().equals("copper_inscriptions")){CodexPaint.text(g,font,"Камнерез берёт только слова из кодексов в моём рюкзаке. Воск и потемнение скрывают знак, но не меняют его.",left,y+76,132,10);return;}if(CodexScreen.documentedRite(node)){CodexPaint.text(g,font,"Великое заклинание. Полная формула записана на следующих страницах. В выживании пока недоступно.",left,y+76,132,10);return;}if(node.id().startsWith("rite:")){CodexPaint.text(g,font,"Эта запись не собирается на верстаке. Её строки ещё ждут своего источника.",left,y+76,132,10);return;}if(node.id().equals("transformation")){item(g,Items.TORCH.getDefaultInstance(),left,top+10);g.drawString(font,"→",left+28,top+14,CodexPaint.INK,false);item(g,MagicLamps.DURABLE_TORCH_ITEM.toStack(),left+48,top+10);item(g,Items.SEA_LANTERN.getDefaultInstance(),left,top+42);g.drawString(font,"→",left+28,top+46,CodexPaint.INK,false);item(g,MagicLamps.DURABLE_LANTERN_ITEM.toStack(),left+48,top+42);CodexPaint.text(g,font,"Слово перемен: свет сохраняет форму, но больше не угасает.",left,top+72,132,4);return;}if(node.id().equals("mana_potion")){item(g,Items.GLASS_BOTTLE.getDefaultInstance(),left,top+10);item(g,MagicContent.MANA_CORE.toStack(),left+22,top+10);item(g,Items.AMETHYST_SHARD.getDefaultInstance(),left+44,top+10);g.drawString(font,"→",left+66,top+14,CodexPaint.INK,false);item(g,net.minecraft.world.item.alchemy.PotionContents.createItemStack(Items.POTION,MagicContent.MANA),left+86,top+10);CodexPaint.text(g,font,"Станция наполнения: бутылочка в центре, образцы рядом. Красная пыль продлевает готовый настой в варочной стойке.",left,top+42,132,8);return;}var mc=Minecraft.getInstance();if(mc.level==null)return;String targetIcon=node.icon();if(node.id().equals("midnight_wood")){int i=spread-pages.size()/2;targetIcon=i==1?"otherworld_dream_bed":i==2?"magic_grass_block":node.icon();}if(node.id().equals("archivist_table")&&spread-pages.size()/2==1)targetIcon="monocle";if(recipeCount()==4){String pre=node.id().equals("arcane_armor")?"arcane_":node.id().equals("archivist_robes")?"archivist_":"mage_";targetIcon=pre+List.of("helmet","chestplate","leggings","boots").get(Math.clamp(spread-pages.size()/2,0,3));}if(node.id().equals("archivist_cabinet")&&spread-pages.size()/2==1)targetIcon="manuscript_cabinet";final String recipeIcon=targetIcon;var match=mc.level.getRecipeManager().getRecipes().stream().filter(r->r.value() instanceof CraftingRecipe&&!r.value().getResultItem(mc.level.registryAccess()).isEmpty()&&net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(r.value().getResultItem(mc.level.registryAccess()).getItem()).toString().equals("kelmagic:"+recipeIcon)).findFirst().orElse(null);if(match==null){CodexPaint.text(g,font,"Для этой записи пока нет отдельной схемы изготовления.",left,top+10,132,9);return;}var recipe=(CraftingRecipe)match.value();var ing=recipe.getIngredients();int columns=recipe instanceof ShapedRecipe s?s.getWidth():3;for(int i=0;i<ing.size()&&i<9;i++){int xx=left+(i%columns)*22,yy=top+(i/columns)*22;g.fill(xx,yy,xx+20,yy+20,0x40634732);var options=ing.get(i).getItems();if(options.length>0)item(g,options[(int)(System.currentTimeMillis()/1300%options.length)],xx+2,yy+2);}g.drawString(font,"→",left+71,top+27,CodexPaint.INK,false);var result=recipe.getResultItem(mc.level.registryAccess());item(g,result,left+87,top+23);CodexPaint.text(g,font,(parent.creativeResearch()?"Выход: "+result.getCount()+". ":"")+(dev.kelmagic.resonance.InfusionRecipes.uses(result)?"Станция наполнения.":recipe instanceof ShapedRecipe?"Верстак.":"Без определённой формы."),left,top+75,132,3);}
 @Override public boolean mouseClicked(double mx,double my,int button){return super.mouseClicked(mx/uiScale,my/uiScale,button);}
 @Override public boolean mouseReleased(double mx,double my,int button){return super.mouseReleased(mx/uiScale,my/uiScale,button);}
 @Override public void onClose(){if(parent.tableView()!=null)parent.tableView().back(parent);else Minecraft.getInstance().setScreen(parent);}
 @Override public boolean isPauseScreen(){return false;}
}
